"""One-time recovery for Assessment e5ce22fc-b8f5-4516-998a-bff5bbfe6983
(curriculum b9af6768-efa6-4127-9e31-19e788fc46bf, "State Management —
Context, Lifting State").

Generation genuinely succeeded — Claude produced a complete, well-formed
assessment — but AnthropicLLMAdapter._parse_json() failed on an unescaped
literal quote inside markdown emphasis (**"Proceed to Delivery"**), which
ended the JSON string early. That parser bug is now fixed (see
_repair_unescaped_inner_quotes in app/adapters/anthropic_llm.py); this
script re-parses the exact raw text Claude originally returned (captured
from the Render log at the time of the incident, embedded below as
base64) through the FIXED parser and writes the recovered content
straight to the existing Assessment row. No new LLM call is made.

Run once, from the repo root, after this fix is deployed:
    python3 scripts/recover_e5ce22fc.py

Safe to leave in the repo afterward — the asserts below make a rerun
after a successful first run fail immediately (status is no longer
needs_manual_diagnosis, and assessment_text is no longer None), so it
cannot double-write.
"""

import base64
import sys
from pathlib import Path

# Make `app` importable regardless of the invoking cwd — this script's own
# directory (scripts/) is what Python puts on sys.path by default, not the
# repo root the `app` package actually lives in.
sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

RAW_B64 = ""

raw_text = base64.b64decode(RAW_B64).decode("utf-8")

from app.adapters.anthropic_llm import AnthropicLLMAdapter
from app.database import SessionLocal
from app.dependencies import _email
from app.models.assessment import Assessment, AssessmentStatus
from app.services.email_service import EmailService

ASSESSMENT_ID = "e5ce22fc-b8f5-4516-998a-bff5bbfe6983"
CURRICULUM_ID = "b9af6768-efa6-4127-9e31-19e788fc46bf"

# No API client construction, no network/LLM call — _parse_json is pure text parsing.
adapter = AnthropicLLMAdapter.__new__(AnthropicLLMAdapter)
data = adapter._parse_json(raw_text)
assert set(data.keys()) >= {"assessment_text", "rubric", "duration_minutes"}, data.keys()
print("Parsed OK:", {k: (len(v) if isinstance(v, str) else v) for k, v in data.items()})

db = SessionLocal()
try:
    assessment = db.get(Assessment, ASSESSMENT_ID)
    assert assessment is not None, "assessment not found"
    assert assessment.curriculum_id == CURRICULUM_ID, assessment.curriculum_id
    assert assessment.status == AssessmentStatus.needs_manual_diagnosis, assessment.status
    assert assessment.assessment_text is None, "already has content — refusing to overwrite"

    assessment.assessment_text = data["assessment_text"]
    assessment.rubric = data["rubric"]
    assessment.duration_minutes = int(data["duration_minutes"])
    assessment.status = AssessmentStatus.active
    db.commit()
    print("Assessment row updated: status=active, assessment_text/rubric/duration_minutes set.")

    EmailService(db, _email).send_assessment_email(ASSESSMENT_ID)
    print("send_assessment_email triggered successfully.")
finally:
    db.close()
